ADD2 = {'甲': [(2, '元分析同时报告了成套实践与单项实践的差，但进入汇总的原始研究没有一项能排除反向因果。')], '乙': [(2, '两侧条件的例子：一个只在这家企业有价值的技能，若员工不这么认为，他照样会去外面试；外部雇主看不见的技能，市场不会付钱。'), (5, '把留人的着力点从技能移到激励，也意味着人力资源部门要能说出「只有我们能给」的到底是什么。')], '丙': [(2, '排名下滑的幅度在跳槽后第一年最大，随后部分恢复，但五年内多数没有回到原位。'), (5, '这一比值的分母是跳槽前的绩效，因此它自动排除了「本来就在下滑所以才跳槽」这一解释的一部分。')], '丁': [(2, '两种校正的差别在于把现职员工当成已经被筛过的群体，还是当成与求职者同分布的群体。'), (5, '实务上这意味着招聘系统里最贵的那道认知测验，其相对价值在两种口径下差一倍。')], '戊': [(2, '时间边界的另一面是成本：淘汰与补充的费用逐年累积，而潜力的增量逐年递减，交点在第三到第五年之间。'), (5, '校准委员会的效果同时说明，原先归咎于「强制分布」的很多问题，实际来自单个主管打分的宽严不一。')], '己': [(2, '三层定义里最有争议的是「特质敬业」——若敬业是一种稳定的人格特质，企业能改变的就很少。'), (5, '企业采购敬业度调查时，可以直接向供应商索要这个相关系数，多数供应商拿不出来。')], '庚': [(2, '从「组织设计工作」到「员工改造工作」，责任的位置也随之移动——工作不合适，先问的是员工有没有再造。'), (5, '把四个维度分开报告是最小的改动，而多数已发表研究没有做。')], '辛': [(2, '这条分岔也解释了为什么关于多样性的公开争论永远各说各话：一方引的是人口学多样性的证据，另一方引的是任务相关多样性的证据。'), (5, '咨询报告与学术元分析的读数在这一条上分手，而企业采购的多是前者。')], '一': [(3, '配对简历按种族与性别各换名字，每家企业收到的份数足以估出自己的差距，这是与此前市场层通讯实验最大的设计差别。'), (5, '名单式执法的代价也在这里：被点名的企业可以改招聘流程，也可以改成不再回任何人的电话。')], '二': [(2, '模型的关键在于雇主的预期：一旦知道给某人涨薪会引来全体要求，雇主在每次谈判里的让步都会变小。'), (5, '欧盟指令要求企业在招聘时公布薪酬区间并报告性别差距，这两项恰是美国各州多数没有做的。')], '三': [(2, '签署率在不可执行的加利福尼亚州与可执行的佛罗里达州几乎一样，是「默认条款」这一判断最直接的读数。'), (5, '规则被叫停后，各州立法成了主战场——2023 年以来明尼苏达等州已通过州级禁令。')], '四': [(2, '六个动作里「替换」与「奖惩」最接近传统的主管权力，「记录」与「评级」则是主管做不到的规模。'), (5, '不透明本身成为控制手段，意味着公开规则不只是公平问题，也是效率问题——猜测消耗了本可以用在工作上的判断。')], '五': [(2, '改为持续反馈的企业通常保留了一个内部评分，只是不再告诉员工——分数从可见变成不可见。'), (5, '四个目的拆开之后，薪酬用相对排名、发展用具体反馈、法律举证用书面记录，各自的评分不必相同。')], '六': [(2, '「学位重置」这个说法的证据基础是公告文本里学位一词的消失，而不是任何一次录用的变化。'), (5, '落差最小的企业是那些同时改了面试与评估工具的企业，它们在报告里被称为「领先者」，占样本不到四成。')], '七': [(2, '留人效应的量纲是离职率而不是满意度，这使它可以直接换算成招聘与培训的成本。'), (5, '选择效应意味着比较远程与到岗员工的横截面数据几乎一定会高估远程的负效应。')], '八': [(2, '唯一有正效应的志愿活动，其机制被解释为改变了社会关系与意义感，而不是教会员工调节压力。'), (5, '落差的另一半来自干预的形态：八周结构化课程与应用里的五分钟练习被算成同一类。')], '九': [(2, '把心理安全当成个人特质去测，等于把一个关于团队的命题改写成关于人的命题，测量的层级随之错位。'), (5, '回到团队层意味着结果变量也要回到可观察的行为——报错次数、异议次数——而不是问卷得分。')], '十': [(2, '压缩的机制是工具把高绩效坐席的应答模式学下来，实时提示给新手；老手本就知道，所以提升不大。'), (5, '工资未变的一种解释是节省的时间被用在了更多任务上而不是更少工时，这一点数据里看得见。')], '十一': [(2, '透明悖论的要害是把「可见」拆成两件事：对主管可见与对同事可见，工人改进技巧时躲的是前者。'), (5, '元分析同时发现，监控被解释为用于发展而非惩罚时，对态度的负效应明显减弱。')], '十二': [(2, '分类匹配的加强意味着高工资的人越来越集中在高工资的企业，两种效应相乘而不是相加。'), (5, '下修之后，「换一家企业能涨多少」这个人力资源实务最关心的数，在多数国家仍显著为正，只是比十年前的估计小。')]}

ADD3 = {'丙': [(4, '这条反例的样本是职业球队，明星的可替代性与知识型企业不同，但机制——队友在明星在场时减少探索——在两种组织里都说得通。')], '丁': [(4, 'Sackett 等在回应里承认，若能拿到原始研究的设计信息，两种口径可以各算各的，而这正是元分析原料所缺的。')], '戊': [(4, '校准的代价是主管们要为每个下属的分数当面辩护，企业实测的会议时间是每轮考核数十小时。')], '己': [(4, '元分析的作者据此建议：在证明敬业度有增量效度之前，研究者应把它与倦怠一起报告，而不是替换。')], '庚': [(4, '回顾还发现再造研究几乎全部来自欧洲与东亚的白领样本，蓝领与零工岗位的再造空间本就小，几乎没被测过。'), (6, '对一线主管而言，这条读数的用处是把「请员工自己再造」这类建议限定在增加资源与挑战的方向上。')], '辛': [(4, '复现的作者把差异归因于原研究对权重与缺失值的处理，并公开了全部代码，原作者的回应承认了部分错误。'), (6, '两条反证合起来说的是：商业论证与学术证据在这一条上已经分手，而多数企业的多样性政策仍引用前者。')], '一': [(4, 'Kline 等的应对是用经验贝叶斯收缩把噪声大的企业拉向均值，并只公布收缩后仍显著的企业，这正是 2024 年排行的做法。'), (6, '两块面板的共同问题是：分布上的读数比均值更有信息，而政策与教学通常只用均值。')], '二': [(4, '高校样本的特殊之处是工资本就相对透明、议价空间小，这可能正是透明在那里不压低工资的原因。'), (6, '欧盟指令 2026 年起适用，将是第一次在同一制度框架下、跨多个国家同时观察三种效应的机会。')], '三': [(4, '两组读数并不矛盾：条款的效应取决于它保护的是雇主的投资还是雇主的惯性，而多数签署者属于后一类。'), (6, 'FTC 规则的经济分析引用的正是本条这批研究，规则被叫停后，这批研究成了各州立法辩论的标准材料。')], '四': [(4, '司机把控制视为正当的一个条件是规则可预期——派单逻辑虽不公开，但结果稳定；停用规则不可预期，抵抗就集中在那里。'), (6, '两块面板的共同缺口是长期结局：被算法管理的工作者五年后的收入与去向，至今没有一项追踪。')], '五': [(4, '研究用的是多家企业多年的人事记录，评分与结局之间隔着可核的时间，这是此前用问卷做的评级研究做不到的。'), (6, '去评级化在实务界的退潮——多家宣布取消的企业数年后恢复了某种形式的评分——是这条读数最直接的现场印证。')], '六': [(4, '这条反向解释也预测：一旦劳动力市场转松，取消了学位要求的公告会把要求加回去，而这正是 2024 年报告里部分企业的做法。'), (6, '技能评估工具的缺席也解释了落差为什么集中在中等技能岗位——那里既没有职业执照可以替代学位，也没有现成的测验。')], '七': [(4, '全远程的负效应集中在新员工与需要指导的岗位，这与携程实验里两天在家仍保留三天面对面的设计正好互补。'), (6, '远程岗位吸引更多申请者这一读数，对招聘部门的含义是筛选负担上升，而不只是候选池扩大。')], '八': [(4, '两类读数的差别还在结果变量：随机试验多测干预后数周的压力量表，横截面测的是任何时点的福祉，两者不是一个量。'), (6, '把干预作用于工作意味着人力资源部门要动工时、排班与主管，这三样恰是它权限最小的地方。')], '九': [(4, '这项实验的样本是学生团队，任务是有作弊机会的决策任务，规模不大，但它是少数直接测量心理安全负面结局的研究之一。'), (6, '提出者的自我修正给出的操作建议是：用团队层的报错与异议次数替代个人问卷，这正是本条的量纲。')], '十': [(4, '这项实验的被试是精英咨询顾问，任务由研究者设计并预注册，边界外的那项任务是刻意加入的。'), (6, '两条接口合起来的读数是：被压缩的是可编码的那部分技能，明星与老手剩下的价值集中在工具边界之外。')], '十一': [(4, '服装厂实验的产量数字只对工人自己可见，不进入奖惩，这是它与手机工厂实验最关键的设计差别。'), (6, '两块面板都没有回答的是：当数字同时给主管与工人看时，两种效应哪一种占上风。')], '十二': [(4, '限制流动偏误的直觉是：一家企业若只有少数人流进流出，它的效应就靠这几个人估，噪声被当成了企业差异。'), (6, '方法争论之外，匹配数据带来的另一变化是研究对象——从愿意填问卷的企业变成一个国家的全部企业。')]}

ADD4 = {'三': [(3, '州层面的自然实验多利用可执行程度的立法变化，比较变化前后雇员的跨企业流动与工资增长。')], '四': [(3, '零工平台之外，仓储与配送的算法排班研究也进入了汇总，那里的控制对象是排班而不是派单。')], '六': [(3, '公告数据的另一个限制是它只覆盖在线发布的岗位，靠内推与中介填补的岗位不在其中。'), (4, '紧缺与过剩的判定用的是各都市区的失业率，同一职业在不同都市区的学位要求随之各异。')], '七': [(3, '两组员工的晋升在两年内没有差别，这一读数针对的正是「在家会被忘记」这一常见担心。')], '九': [(3, '一个常被引的现场例子是医院团队：报错多的团队并不是错得多，而是敢报的多，这是概念最初的经验来源。')], '十': [(3, '客户评价的改善集中在新手组，老手组的客户评价与接入前几乎相同。')], '十一': [(3, '围帘线的工人在访谈里说出的改进技巧，多数是对标准操作程序的偏离，这正是他们在被看见时不做的事。'), (5, '监控研究多以问卷测态度、以主管评分测绩效，用客观产出的研究在元分析里只占少数。')], '十二': [(3, '西德样本覆盖 1985 至 2009 年的全部全职男性雇员，企业效应用同期在多家企业工作过的人识别。')]}

